const templates = [
  { id: 't_1188', title: 'AI email triage to Sheets', installs: 41200, has_evals: true, eval_pass: 0.97, fuzz_survival: 0.91, injection_resistance: 0.88, cost_variance: 0.12, days_since_verified: 6, incidents_90d: 1 },
  { id: 't_2054', title: 'Autonomous invoice payer', installs: 8800, has_evals: false, eval_pass: 0, fuzz_survival: 0.34, injection_resistance: 0.29, cost_variance: 0.71, days_since_verified: 402, incidents_90d: 17 },
  { id: 't_3391', title: 'RAG over your Notion', installs: 26500, has_evals: true, eval_pass: 0.82, fuzz_survival: 0.64, injection_resistance: 0.41, cost_variance: 0.38, days_since_verified: 88, incidents_90d: 6 },
  { id: 't_4407', title: 'Slack standup summariser', installs: 15900, has_evals: true, eval_pass: 0.94, fuzz_survival: 0.87, injection_resistance: 0.79, cost_variance: 0.09, days_since_verified: 21, incidents_90d: 0 }
];
return [{ json: { templates: templates } }];

const d = $input.first().json;
const scored = d.templates.map(function (t) {
  const freshness = Math.max(0, 1 - (t.days_since_verified / 180));
  const incidentDrag = Math.max(0, 1 - (t.incidents_90d / 10));
  const raw = (t.eval_pass * 0.30) + (t.fuzz_survival * 0.20) + (t.injection_resistance * 0.20) +
              ((1 - Math.min(1, t.cost_variance)) * 0.10) + (freshness * 0.10) + (incidentDrag * 0.10);
  const capped = t.has_evals ? raw : Math.min(raw, 0.49);
  const pct = Math.round(capped * 100);
  let grade = 'D';
  if (pct >= 85) { grade = 'A'; } else if (pct >= 70) { grade = 'B'; } else if (pct >= 55) { grade = 'C'; }
  const weakest = [
    { k: 'no evals at all', v: t.has_evals ? 1 : 0 },
    { k: 'falls over on malformed input', v: t.fuzz_survival },
    { k: 'prompt injection gets through', v: t.injection_resistance },
    { k: 'cost swings wildly per run', v: 1 - Math.min(1, t.cost_variance) },
    { k: 'not verified in months', v: freshness }
  ].sort(function (a, b) { return a.v - b.v; })[0];
  return { id: t.id, title: t.title, installs: t.installs, trust: pct, grade: grade,
    biggest_problem: weakest.k, exposed_installs: grade === 'D' ? t.installs : 0 };
});
const risky = scored.filter(function (s) { return s.grade === 'D'; });
const exposed = scored.reduce(function (a, s) { return a + s.exposed_installs; }, 0);
const worst = scored.slice().sort(function (a, b) { return a.trust - b.trust; })[0];
const say = 'The template library has no quality signal on it at all today - a template with 8,800 installs and 17 incidents looks exactly like one with 41,200 installs and zero. ' +
  'Scoring them puts ' + risky.length + ' in the danger band, covering ' + exposed + ' installs. ' +
  'Worst is \"' + worst.title + '\" at ' + worst.trust + '/100: ' + worst.biggest_problem + '. ' +
  'A template with no evals is capped at 49 no matter how popular it is, because popularity is not evidence.';
const headline = risky.length > 2 ? 'crisis' : (risky.length > 0 ? 'flagged' : 'healthy');
return [{ json: { plain_english: say, headline: headline, ledger: scored, exposed_installs: exposed } }];
